function artAssetSvg(p,i){
 const base=p.palette||['#f3eee7','#24384e','#e47f55','#8c9b89'],v=Math.floor(i/10),shift=v%4;
 const varied=Object.assign({},p,{palette:[base[0],base[(1+shift)%4],base[(2+shift)%4],base[(3+shift)%4]]});
 const body=artSvg(varied,i),markerX=72+(v%5)*105,markerY=80+(v%3)*22;
 const variation=(p.assetKind==='pattern'||p.assetKind==='poster'||p.assetKind==='social'||p.assetKind==='tshirt'||p.assetKind==='invitation')?'':'<g opacity=".72"><circle cx="'+markerX+'" cy="'+markerY+'" r="'+(7+(v%4)*3)+'" fill="'+varied.palette[2]+'"/><circle cx="'+(600-markerX)+'" cy="'+(600-markerY)+'" r="'+(5+(v%3)*3)+'" fill="'+varied.palette[3]+'"/></g>';
 return '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 600 600"><title>'+p.title+' / Design '+String(i+1).padStart(2,'0')+'</title>'+body+variation+'</svg>';
}
function crc32(bytes){let crc=-1;for(let i=0;i<bytes.length;i++){crc^=bytes[i];for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xEDB88320:0);}return (crc^-1)>>>0;}
function zipBlob(files){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;files.forEach(f=>{const name=enc.encode(f.name),data=typeof f.data==='string'?enc.encode(f.data):f.data,crc=crc32(data),h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint16(8,0,true);v.setUint16(10,0,true);v.setUint16(12,0x21,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);v.setUint16(28,0,true);h.set(name,30);locals.push(h,data);const ch=new Uint8Array(46+name.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint16(10,0,true);cv.setUint16(12,0,true);cv.setUint16(14,0x21,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint16(30,0,true);cv.setUint16(32,0,true);cv.setUint16(34,0,true);cv.setUint16(36,0,true);cv.setUint32(38,0,true);cv.setUint32(42,offset,true);ch.set(name,46);centrals.push(ch);offset+=h.length+data.length;});const centralSize=centrals.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(4,0,true);ev.setUint16(6,0,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,centralSize,true);ev.setUint32(16,offset,true);ev.setUint16(20,0,true);return new Blob([...locals,...centrals,end],{type:'application/zip'});}
function svgToPng(svg,width,height){return new Promise((resolve,reject)=>{const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=width||1200;canvas.height=height||width||1200;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(b=>{URL.revokeObjectURL(url);if(!b){reject(new Error('PNG export failed'));return;}b.arrayBuffer().then(buf=>resolve(new Uint8Array(buf))).catch(reject);},'image/png');}catch(e){URL.revokeObjectURL(url);reject(e);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Artwork render failed'));};img.src=url;});}
async function buildArtBundle(p){const files=[],formats=p.assetFormats||['SVG'],n=Math.max(1,Number(p.assetCount)||12);for(let i=0;i<n;i++){const svg=artAssetSvg(p,i),name=p.slug+'-'+String(i+1).padStart(2,'0');files.push({name:'SVG/'+name+'.svg',data:svg});if(formats.includes('PNG')){try{files.push({name:'PNG/'+name+'.png',data:await svgToPng(svg,1200)});}catch(e){}}}files.push({name:'README.txt',data:'CAREERPILOT DIGITAL / ORIGINAL ART COLLECTION\n'+p.title+'\n\n'+p.description+'\n\nINCLUDED\n'+(p.includedItems||[]).map(x=>'- '+x).join('\n')+'\n\nSVG files are editable in compatible vector software. PNG exports have transparent backgrounds where supported. Review applicable usage terms before commercial redistribution.'});return zipBlob(files);}
async function buildWeddingTemplate(p,fields){const files=[],pages=window.CareerPilotWedding.buildFiles(p,fields||p.sampleFields||{});for(const f of pages){files.push({name:'EDITABLE SVG/'+f.name,data:f.data});try{files.push({name:'PNG EXPORT/'+f.name.replace(/\.svg$/i,'.png'),data:await svgToPng(f.data,1200,1680)});}catch(e){}}files.push({name:'README.txt',data:'CAREERPILOT DIGITAL / EDITABLE WEDDING INVITATION\n'+p.title+'\n\nEdit the couple names, wedding date, time, venue, RSVP details and dress code in the CareerPilot browser editor. SVG text remains editable in Inkscape, Adobe Illustrator, Affinity Designer and compatible vector editors. PNG files are high-resolution exports. Confirm final page size, bleed and printer requirements before printing. Replace all sample details before sharing.'});return zipBlob(files);}
async function downloadWeddingKit(p,fields){try{toast.textContent='Preparing your editable wedding invitation kit...';toast.classList.add('show');const blob=await buildWeddingTemplate(p,fields),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=p.slug+'-editable-kit.zip';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);toast.textContent='Your editable kit is ready.';setTimeout(()=>toast.classList.remove('show'),2600);}catch(e){toast.textContent='The wedding kit could not be prepared. Please try again.';setTimeout(()=>toast.classList.remove('show'),3500);}}
async function downloadGeneratedProduct(id){const p=products.find(x=>x.id===id);if(!p)return;try{toast.textContent=p.assetType==='art-bundle'?'Preparing your artwork bundle...':p.assetType==='wedding-template'?'Preparing your editable invitation kit...':'Preparing your '+p.pages+'-page PDF...';toast.classList.add('show');const blob=p.assetType==='art-bundle'?await buildArtBundle(p):p.assetType==='wedding-template'?await buildWeddingTemplate(p):buildGeneratedPdf(p),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=p.slug+(p.assetType==='art-bundle'?'-bundle.zip':p.assetType==='wedding-template'?'-editable-kit.zip':'.pdf');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);toast.textContent='Your download is ready.';setTimeout(()=>toast.classList.remove('show'),2600);}catch(e){toast.textContent='This download could not be prepared. Please try again.';setTimeout(()=>toast.classList.remove('show'),3500);}}



function card(p){
 const bg=colours[p.categoryKey]||'#172a43',alt=p.assetType==='wedding-template'?'Editable invitation artwork preview for '+p.title:p.assetType==='art-bundle'?'Actual artwork samples included in '+p.title:'Actual interior worksheet page from '+p.title;
 let visual='';
 if(p.assetType==='wedding-template'){const svg=window.CareerPilotWedding.render(p,0,p.sampleFields||{});visual='<div class="product-page-preview wedding-card-preview"><img src="data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)+'" alt="'+esc(alt)+'" loading="lazy"><span>EDITABLE INVITATION DESIGN</span></div>';}
 else if(p.previewImage)visual='<div class="product-page-preview"><img src="'+esc(p.previewImage)+'" alt="'+esc(alt)+'" loading="lazy"><span>'+(p.assetType==='art-bundle'?'ACTUAL ARTWORK / SAMPLE SHEET':'ACTUAL INTERIOR PAGE')+'</span></div>';
 else visual='<div class="product-cover" style="--cover-bg:'+bg+'"><div class="cover-top"><span>CAREERPILOT DIGITAL</span><span>'+esc(p.format)+'</span></div><div class="cover-middle"><span class="cover-category">'+esc(p.category)+'</span><h3>'+esc(p.title)+'</h3><p>'+esc(p.description)+'</p></div><div class="cover-bottom"><span>'+esc(p.id)+'</span><span>ORIGINAL DIGITAL EDITION</span></div></div>';
 const size=p.assetType==='art-bundle'?(p.assetCount+' ORIGINAL ASSETS'):(p.pages+' '+(p.pages===1?'PAGE':'PAGES'));
 const download='<button type="button" data-download-product="'+esc(p.id)+'">'+(p.assetType==='art-bundle'?'Download ZIP':p.assetType==='wedding-template'?'Download editable kit':'Download PDF')+' <span aria-hidden="true">↓</span></button>';
 return '<article class="product-card">'+visual+'<div class="product-card-body"><div class="product-meta"><span class="product-category">'+esc(p.category)+'</span><span class="product-format">'+esc(p.format)+'</span></div><h3>'+esc(p.title)+'</h3><p>'+esc(p.description)+'</p><div class="product-card-actions"><button type="button" data-preview="'+esc(p.id)+'">'+(p.assetType==='wedding-template'?'Edit & preview':'Preview product')+' <span aria-hidden="true">↗</span></button>'+download+'</div><div class="product-card-size">'+esc(size)+'</div></div></article>';
}
