 dialog.showModal();const notes=$('#reader-notes'),status=$('#notes-status'),downloadNotes=$('#download-notes'),clearNotes=$('#clear-notes');let saved='';try{saved=localStorage.getItem(noteKey)||'';}catch(e){saved='';}notes.value=saved;
